account_private.sync_username_signin_ind.src:
declare
  old_candidate text;
  new_candidate text;
  lock_candidate text;
  projection_username text;
  projection_alias text;
begin
  if tg_op <> 'INSERT' then old_candidate := lower(trim(coalesce(old.raw_user_meta_data ->> 'username', ''))); end if;
  if tg_op <> 'DELETE' then new_candidate := lower(trim(coalesce(new.raw_user_meta_data ->> 'username', ''))); end if;
  for lock_candidate in
    select candidate from unnest(array[old_candidate, new_candidate]) candidate
    where candidate ~ '^[a-z0-9._-]{2,15}$'
    group by candidate order by candidate
  loop
    perform pg_advisory_xact_lock(hashtextextended('account_username:' || lock_candidate, 0));
  end loop;
  if old_candidate ~ '^[a-z0-9._-]{2,15}$' then
    perform account_private.refresh_username_signin_candidate(old_candidate);
  end if;
  if new_candidate ~ '^[a-z0-9._-]{2,15}$' and new_candidate is distinct from old_candidate then
    perform account_private.refresh_username_signin_candidate(new_candidate);
  end if;
  -- Derived private lookup is maintained in the same Auth row transaction.
  if tg_op = 'DELETE' then
    delete from account_private.username_signin_candidates where user_id = old.id;
  else
    projection_username := lower(btrim(coalesce(new.raw_user_meta_data ->> 'username', '')));
    if projection_username !~ '^[a-z0-9._-]{2,15}$' then projection_username := null; end if;
    projection_alias := case when jsonb_typeof(new.raw_user_meta_data -> 'display_name') = 'string'
      then lower(btrim(new.raw_user_meta_data ->> 'display_name')) else null end;
    if projection_alias !~ '^[a-z0-9._-]{2,15}$' then projection_alias := null; end if;
    if projection_username is null and projection_alias is null then
      delete from account_private.username_signin_candidates where user_id = new.id;
    else
      insert into account_private.username_signin_candidates(user_id, normalized_username, normalized_alias)
      values(new.id, projection_username, projection_alias)
      on conflict(user_id) do update set normalized_username=excluded.normalized_username,normalized_alias=excluded.normalized_alias;
    end if;
  end if;
  return coalesce(new, old);
end;

account_private.refresh_username_signin_.src:
begin
  perform pg_advisory_xact_lock(hashtextextended('account_username:' || candidate, 0));
  delete from account_private.username_signin_index where normalized_username = candidate;
  insert into account_private.username_signin_index (user_id, normalized_username, updated_at)
  select candidate_user.id, candidate, now()
  from auth.users candidate_user
  where lower(trim(coalesce(candidate_user.raw_user_meta_data ->> 'username', ''))) = candidate
    and not exists (
      select 1 from auth.users conflicting_user
      where conflicting_user.id <> candidate_user.id
        and lower(trim(coalesce(conflicting_user.raw_user_meta_data ->> 'username', ''))) = candidate
    );
end;

discordos.set_updated_at().src:
begin
  new.updated_at = now();
  return new;
end;
